 "content": "def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    ink = next(v for row in grid for v in row if v != bg)
    out = [row[:] for row in grid]
    # Connect consecutive collinear marks when at least one endpoint is a
    # terminal (has no mark continuing perpendicular to the line).
    for r in range(h):
        xs = [c for c in range(w) if grid[r][c] == ink]
        for a, b in zip(xs, xs[1:]):
            if b == a + 1:
                continue
            va = (r > 0 and grid[r-1][a] == ink) or (r+1 < h and grid[r+1][a] == ink)
            vb = (r > 0 and grid[r-1][b] == ink) or (r+1 < h and grid[r+1][b] == ink)
            if not (va and vb):
                for c in range(a+1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    for c in range(w):
        ys = [r for r in range(h) if grid[r][c] == ink]
        for a, b in zip(ys, ys[1:]):
            if b == a + 1:
                continue
            ha = (c > 0 and grid[a][c-1] == ink) or (c+1 < w and grid[a][c+1] == ink)
            hb = (c > 0 and grid[b][c-1] == ink) or (c+1 < w and grid[b][c+1] == ink)
            if not (ha and hb):
                for r in range(a+1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    return out
"
