        return out
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    # Complete the perimeter of the bounding rectangle in color 2.
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if (r == r0 or r == r1 or c == c0 or c == c1) and grid[r][c] == bg:
                out[r][c] = 2
    # Treat original ink and completed perimeter as strokes. Bridge aligned
    # gaps if at least one endpoint terminates rather than continuing
    # perpendicular to the proposed bridge.
    def occupied(r, c):
        return 0 <= r < h and 0 <= c < w and out[r][c] != bg
    for r in range(r0, r1 + 1):
        xs = [c for c in range(c0, c1 + 1) if occupied(r, c)]
        for a, b in zip(xs, xs[1:]):
            if b - a <= 1:
                continue
            a_through = occupied(r - 1, a) or occupied(r + 1, a)
            b_through = occupied(r - 1, b) or occupied(r + 1, b)
            if not (a_through and b_through):
                for c in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2
    for c in range(c0, c1 + 1):
        ys = [r for r in range(r0, r1 + 1) if occupied(r, c)]
